function progressRing(pct,center,label,cls=''){const r=26,c=2*Math.PI*r,p=Math.max(0,Math.min(1,pct||0));return `<span class="ring ${cls}" role="img" aria-label="${esc(label)} ${Math.round(p*100)}%"><svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="${r}" class="ring-bg"/><circle cx="32" cy="32" r="${r}" class="ring-fg" stroke-dasharray="${(c*p).toFixed(1)} ${c.toFixed(1)}" transform="rotate(-90 32 32)"/></svg><b>${center}</b></span>`}
